(6, '2551', '255106', 'ศิลปะ'),
(7, '2551', '255107', 'การงานอาชีพและเทคโนโลยี'),
(8, '2551', '255108', 'ภาษาต่างประเทศ'),
(10, '2560', '256001', 'คณิตศาสตร์'),
