(4261, 2569, 4218, 'ที่ รย 0021/4218', '2026-08-19', 'สำนักงานป้องกันและบรรเทาสาธารณภัยจังหวัดระยอง', '-', 'จองเลขอัตโนมัติ', 'ระบบอัตโนมัติ', 1, '', '2026-08-19', '6a858cb2233d3', '1529900141630', 0, 1),
(4262, 2569, 4219, 'ที่ รย 0021/4219', '2026-08-20', 'สำนักงานป้องกันและบรรเทาสาธารณภัยจังหวัดระยอง', 'ผู้อำนวยการกองกฎหมาย', 'การขอเปลี่ยนแปลงสิทธิ์ผู้ใช้งานระบบฐานข้อมูลเงินทดรองราชการเพื่อช่วยเหลือผุ้ประสบภัยพิบัติกรณีฉุกเฉิน', '', 3, '', '2026-08-20', '1787199391x639479413', '1529900141630', 0, 1),
(4263, 2569, 4220, 'ที่ รย 0021/4220', '2026-08-20', 'สำนักงานป้องกันและบรรเทาสาธารณภัยจังหวัดระยอง', 'ผู้ว่าราชการจังหวัดระยอง', 'การนำส่งดอกเบี้ยเงินฝากธนาคาร ของมูลนิธิราชประชานุเคราะห์ประจำจังหวัด งานบรรเทาทุกข์', 'คุณปวิณณา จันทวงษ์', 3, '', '2026-08-20', '1787201838x639459032', '1529900141630', 0, 1),
(4264, 2569, 4221, 'ที่ รย 0021/4221', '2026-08-20', 'สำนักงานป้องกันและบรรเทาสาธารณภัยจังหวัดระยอง', 'ผู้ว่าราชการจังหวัดระยอง', 'การจัดทำห้องประชุมภายในสำนักงานป้องกันและบรรเทาสาธารณภัยจังหวัดระยอง', 'คุณพิชญา เชื้อทับทิม', 3, '', '2026-08-20', '1787201931x928061841', '1529900141630', 0, 1),
(4265, 2569, 4222, 'ที่ รย 0021/4222', '2026-08-20', 'สำนักงานป้องกันและบรรเทาสาธารณภัยจังหวัดระยอง', 'หัวหน้าสำนักงานป้องกันและบรรเทาสาธารณภัยจังหวัดระยอง', 'ยกเลิกคำสั่งและแต่งตั้งเจ้าหน้าที่ปฏิบัติหน้าที่ขับรถส่วนกลาง สำนักงานป้องกันและบรรเทาสาธารณภัยจังหวัดระยอง', 'คุณวรรณภา ภูโสภา', 1, '', '2026-08-20', '1787202219x1122563533', '1529900141630', 0, 1),
(4266, 2569, 4223, 'ที่ รย 0021/4223', '2026-08-20', 'สำนักงานป้องกันและบรรเทาสาธารณภัยจังหวัดระยอง', 'ผู้ว่าราชการจังหวัดระยอง', 'ขออนุมัติเบิก-จ่ายเงินค่าสาธารณูปโภค (ค่าดทรศัพท์เคลื่อนที่ เดือนกรกฎาคม 2569)  ', 'คุณพจมาลย์ กันสุข', 1, '', '2026-08-20', '1787202325x946097065', '1529900141630', 0, 1);
